    ('54522043-990b-496d-bba6-77b6a2c2058e', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 4 AND code = 'VIE') AND code = 'C3' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'multiple_choice' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'easy' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'apply' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Xác định phát biểu đúng trong số các phương án sau:', 'Xac dinh phat bieu dung trong so cac phuong an sau:', 'Các vế trong câu ghép có thể nối với nhau bằng quan hệ từ.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Tiếng Việt','Lớp 4']::TEXT[], true, 'approved', 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
    ('df54b081-8c93-4257-993c-cd6d35437a55', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 4 AND code = 'VIE') AND code = 'C4' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'true_false' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'easy' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'analyze' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Từ ghép là từ được tạo bởi hai tiếng có nghĩa ghép lại, ví dụ ''quần áo''. Câu trên đúng hay sai?', 'Tu ghep la tu duoc tao boi hai tieng co nghia ghep lai, vi du ''quan ao''. Cau tren dung hay sai?', 'Từ ghép là từ được tạo bởi hai tiếng có nghĩa ghép lại, ví dụ ''quần áo''.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Tiếng Việt','Lớp 4']::TEXT[], true, 'approved', 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
    ('70caf853-000f-46a8-bfa2-5547973b793c', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 4 AND code = 'VIE') AND code = 'C5' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'multiple_choice' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'easy' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'evaluate' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Câu nào sau đây nêu đúng kiến thức đã học?', 'Cau nao sau day neu dung kien thuc da hoc?', 'Bài văn tả cây cối thường tả theo trình tự từ rễ, thân, đến lá, hoa, quả.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Tiếng Việt','Lớp 4']::TEXT[], true, 'approved', 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
    ('26ccb33b-46c1-4b41-87da-e03de5698f75', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 4 AND code = 'VIE') AND code = 'C6' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'essay' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'easy' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'create' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Em hãy kể lại một việc tốt mà em đã chứng kiến ở trường hoặc ở nhà.', 'Em hay ke lai mot viec tot ma em da chung kien o truong hoac o nha.', 'Câu hỏi tự luận — chấm theo rubric của giáo viên.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Tiếng Việt','Lớp 4']::TEXT[], true, 'approved', 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
    ('10beed78-e125-4e18-ae7c-5733b52bfb41', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 4 AND code = 'VIE') AND code = 'C1' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'multiple_choice' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'medium' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'remember' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Theo nội dung đã học, phát biểu nào dưới đây đúng?', 'Theo noi dung da hoc, phat bieu nao duoi day dung?', 'Bài văn tả con vật cần miêu tả hình dáng và hoạt động của con vật.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Tiếng Việt','Lớp 4']::TEXT[], true, 'approved', 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
    ('17bd0271-8f66-4db7-8dbd-20773c63e613', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 4 AND code = 'VIE') AND code = 'C2' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'true_false' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'medium' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'understand' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Kể chuyện được chứng kiến là kể lại một sự việc có thật mà em đã thấy. Câu trên đúng hay sai?', 'Ke chuyen duoc chung kien la ke lai mot su viec co that ma em da thay. Cau tren dung hay sai?', 'Kể chuyện được chứng kiến là kể lại một sự việc có thật mà em đã thấy.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Tiếng Việt','Lớp 4']::TEXT[], true, 'approved', 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
    ('51d4c56e-c9a5-4c4c-b2cc-21b39bdbb6dc', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 4 AND code = 'VIE') AND code = 'C3' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'multiple_choice' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'medium' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'apply' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Trong 4 phương án dưới đây, đâu là phương án đúng?', 'Trong 4 phuong an duoi day, dau la phuong an dung?', 'Chủ ngữ là bộ phận trả lời cho câu hỏi ''Ai? Cái gì? Con gì?''.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Tiếng Việt','Lớp 4']::TEXT[], true, 'approved', 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
    ('d204dd9d-39e3-49e0-bbfc-959c48e66835', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 4 AND code = 'VIE') AND code = 'C4' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'true_false' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'medium' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'analyze' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Vị ngữ luôn luôn là một danh từ riêng. Theo em, nhận định trên đúng hay sai?', 'Vi ngu luon luon la mot danh tu rieng. Theo em, nhan dinh tren dung hay sai?', 'Vị ngữ thường nêu hoạt động, trạng thái, đặc điểm của chủ ngữ.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Tiếng Việt','Lớp 4']::TEXT[], true, 'approved', 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
    ('700e1f16-f7e5-44b2-9d6e-f65b250895d9', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 4 AND code = 'VIE') AND code = 'C5' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'multiple_choice' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'medium' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'evaluate' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Hãy chỉ ra nhận định đúng trong các câu sau:', 'Hay chi ra nhan dinh dung trong cac cau sau:', 'Trạng ngữ bổ sung ý nghĩa về thời gian, nơi chốn, nguyên nhân cho câu.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Tiếng Việt','Lớp 4']::TEXT[], true, 'approved', 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
    ('d6d3a220-37c6-4192-b04c-a346f7c39f7d', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 4 AND code = 'VIE') AND code = 'C6' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'true_false' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'medium' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'create' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Con người Việt Nam nổi tiếng với truyền thống hiếu học và cần cù. Câu trên đúng hay sai?', 'Con nguoi Viet Nam noi tieng voi truyen thong hieu hoc va can cu. Cau tren dung hay sai?', 'Con người Việt Nam nổi tiếng với truyền thống hiếu học và cần cù.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Tiếng Việt','Lớp 4']::TEXT[], true, 'approved', 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
