    ('20dade97-7184-4fc9-916f-2eaadbc6cb9d', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 4 AND code = 'VIE') AND code = 'C3' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'multiple_choice' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'hard' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'apply' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Trong 4 phương án dưới đây, đâu là phương án đúng?', 'Trong 4 phuong an duoi day, dau la phuong an dung?', 'Chủ ngữ là bộ phận trả lời cho câu hỏi ''Ai? Cái gì? Con gì?''.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Tiếng Việt','Lớp 4']::TEXT[], true, 'approved', 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
    ('1ceaaac5-f82e-4864-b81a-7920e0e7a243', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 4 AND code = 'VIE') AND code = 'C4' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'true_false' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'hard' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'analyze' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Vị ngữ luôn luôn là một danh từ riêng. Câu trên đúng hay sai?', 'Vi ngu luon luon la mot danh tu rieng. Cau tren dung hay sai?', 'Vị ngữ thường nêu hoạt động, trạng thái, đặc điểm của chủ ngữ.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Tiếng Việt','Lớp 4']::TEXT[], true, 'approved', 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
    ('31550594-6be5-48fc-b29d-1af966aa99c3', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 4 AND code = 'VIE') AND code = 'C5' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'multiple_choice' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'hard' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'evaluate' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Hãy chỉ ra nhận định đúng trong các câu sau:', 'Hay chi ra nhan dinh dung trong cac cau sau:', 'Trạng ngữ bổ sung ý nghĩa về thời gian, nơi chốn, nguyên nhân cho câu.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Tiếng Việt','Lớp 4']::TEXT[], true, 'approved', 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
    ('a8b00800-5aff-4dd5-b131-2148918078da', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 4 AND code = 'VIE') AND code = 'C6' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'true_false' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'hard' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'create' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Con người Việt Nam nổi tiếng với truyền thống hiếu học và cần cù. Theo em, nhận định trên đúng hay sai?', 'Con nguoi Viet Nam noi tieng voi truyen thong hieu hoc va can cu. Theo em, nhan dinh tren dung hay sai?', 'Con người Việt Nam nổi tiếng với truyền thống hiếu học và cần cù.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Tiếng Việt','Lớp 4']::TEXT[], true, 'approved', 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
    ('0475c24c-f64f-433b-833c-e0a24f3570c4', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 4 AND code = 'VIE') AND code = 'C1' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'multiple_choice' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'very_hard' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'remember' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Phát biểu nào dưới đây phù hợp với kiến thức đã học?', 'Phat bieu nao duoi day phu hop voi kien thuc da hoc?', 'Câu hỏi thường dùng các từ nghi vấn như ''ai, gì, sao, thế nào''.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Tiếng Việt','Lớp 4']::TEXT[], true, 'approved', 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
    ('e59497ba-e5c8-40b2-adb5-e6769f9322c8', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 4 AND code = 'VIE') AND code = 'C2' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'true_false' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'very_hard' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'understand' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Đoạn văn miêu tả không cần dùng tính từ. Câu trên đúng hay sai?', 'Doan van mieu ta khong can dung tinh tu. Cau tren dung hay sai?', 'Đoạn văn miêu tả cần dùng nhiều tính từ gợi hình, gợi cảm.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Tiếng Việt','Lớp 4']::TEXT[], true, 'approved', 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
    ('a64432ec-9e17-4682-9c7a-5244d15eec8b', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 4 AND code = 'VIE') AND code = 'C3' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'essay' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'very_hard' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'apply' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Em hãy viết đoạn văn (5-6 câu) miêu tả một loài cây mà em yêu thích.', 'Em hay viet doan van (5-6 cau) mieu ta mot loai cay ma em yeu thich.', 'Câu hỏi tự luận — chấm theo rubric của giáo viên.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Tiếng Việt','Lớp 4']::TEXT[], true, 'approved', 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
    ('ab6cc965-15d7-4d44-b2b1-b44074432477', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 4 AND code = 'VIE') AND code = 'C4' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'true_false' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'very_hard' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'analyze' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Câu ghép chỉ có một vế câu duy nhất. Theo em, nhận định trên đúng hay sai?', 'Cau ghep chi co mot ve cau duy nhat. Theo em, nhan dinh tren dung hay sai?', 'Câu ghép là câu do hai hay nhiều vế câu ghép lại.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Tiếng Việt','Lớp 4']::TEXT[], true, 'approved', 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
    ('8876dfc4-8c21-4c05-876f-1ff6282d41f0', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 4 AND code = 'VIE') AND code = 'C5' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'multiple_choice' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'very_hard' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'evaluate' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Trong các phát biểu sau, phát biểu nào đúng?', 'Trong cac phat bieu sau, phat bieu nao dung?', 'Các vế trong câu ghép có thể nối với nhau bằng quan hệ từ.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Tiếng Việt','Lớp 4']::TEXT[], true, 'approved', 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
    ('d290f535-7c47-4756-a053-10a400baba90', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 4 AND code = 'VIE') AND code = 'C6' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'true_false' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'very_hard' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'create' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Từ ghép là từ chỉ có một tiếng duy nhất. Câu trên đúng hay sai?', 'Tu ghep la tu chi co mot tieng duy nhat. Cau tren dung hay sai?', 'Từ ghép là từ được tạo bởi hai tiếng có nghĩa ghép lại, ví dụ ''quần áo''.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Tiếng Việt','Lớp 4']::TEXT[], true, 'approved', 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
    ('7923dd4d-71a8-496d-8cba-8075076e520a', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 4 AND code = 'VIE') AND code = 'C1' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'multiple_choice' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'easy' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'remember' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Nhận định nào sau đây là chính xác?', 'Nhan dinh nao sau day la chinh xac?', 'Bài văn tả cây cối thường tả theo trình tự từ rễ, thân, đến lá, hoa, quả.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Tiếng Việt','Lớp 4']::TEXT[], true, 'approved', 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
