    ('1bc01d48-5660-4d3f-9b61-30fb720dc258', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 4 AND code = 'VIE') AND code = 'C1' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'multiple_choice' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'medium' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'remember' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Theo nội dung đã học, phát biểu nào dưới đây đúng?', 'Theo noi dung da hoc, phat bieu nao duoi day dung?', 'Bài văn tả con vật cần miêu tả hình dáng và hoạt động của con vật.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Tiếng Việt','Lớp 4']::TEXT[], true, 'approved', 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
    ('b0d0044b-178b-4e4d-b97c-626c1c52ca71', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 4 AND code = 'VIE') AND code = 'C2' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'true_false' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'medium' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'understand' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Kể chuyện được chứng kiến là kể lại một sự việc có thật mà em đã thấy. Câu trên đúng hay sai?', 'Ke chuyen duoc chung kien la ke lai mot su viec co that ma em da thay. Cau tren dung hay sai?', 'Kể chuyện được chứng kiến là kể lại một sự việc có thật mà em đã thấy.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Tiếng Việt','Lớp 4']::TEXT[], true, 'approved', 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
    ('3ee88879-247a-4dd9-b9a9-408a3f98686f', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 4 AND code = 'VIE') AND code = 'C3' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'multiple_choice' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'medium' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'apply' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Trong 4 phương án dưới đây, đâu là phương án đúng?', 'Trong 4 phuong an duoi day, dau la phuong an dung?', 'Chủ ngữ là bộ phận trả lời cho câu hỏi ''Ai? Cái gì? Con gì?''.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Tiếng Việt','Lớp 4']::TEXT[], true, 'approved', 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
    ('91d35b28-7bb8-4ff5-9956-ba30e505ec0e', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 4 AND code = 'VIE') AND code = 'C4' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'true_false' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'medium' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'analyze' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Vị ngữ luôn luôn là một danh từ riêng. Theo em, nhận định trên đúng hay sai?', 'Vi ngu luon luon la mot danh tu rieng. Theo em, nhan dinh tren dung hay sai?', 'Vị ngữ thường nêu hoạt động, trạng thái, đặc điểm của chủ ngữ.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Tiếng Việt','Lớp 4']::TEXT[], true, 'approved', 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
    ('dec28d0c-3f85-4873-9690-6158c82d63bc', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 4 AND code = 'VIE') AND code = 'C5' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'multiple_choice' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'medium' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'evaluate' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Hãy chỉ ra nhận định đúng trong các câu sau:', 'Hay chi ra nhan dinh dung trong cac cau sau:', 'Trạng ngữ bổ sung ý nghĩa về thời gian, nơi chốn, nguyên nhân cho câu.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Tiếng Việt','Lớp 4']::TEXT[], true, 'approved', 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
    ('c2dba073-8794-46fc-8524-4b953fc8f11e', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 4 AND code = 'VIE') AND code = 'C6' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'true_false' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'medium' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'create' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Con người Việt Nam nổi tiếng với truyền thống hiếu học và cần cù. Câu trên đúng hay sai?', 'Con nguoi Viet Nam noi tieng voi truyen thong hieu hoc va can cu. Cau tren dung hay sai?', 'Con người Việt Nam nổi tiếng với truyền thống hiếu học và cần cù.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Tiếng Việt','Lớp 4']::TEXT[], true, 'approved', 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
    ('2e36abfd-9f4f-4a88-a4a9-6185d44eb4e1', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 4 AND code = 'VIE') AND code = 'C1' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'multiple_choice' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'hard' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'remember' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Phát biểu nào dưới đây phù hợp với kiến thức đã học?', 'Phat bieu nao duoi day phu hop voi kien thuc da hoc?', 'Câu hỏi thường dùng các từ nghi vấn như ''ai, gì, sao, thế nào''.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Tiếng Việt','Lớp 4']::TEXT[], true, 'approved', 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
    ('2231cb75-60bf-4d59-90d8-2af7328ec2f9', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 4 AND code = 'VIE') AND code = 'C2' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'true_false' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'hard' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'understand' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Đoạn văn miêu tả cần dùng nhiều tính từ gợi hình, gợi cảm. Theo em, nhận định trên đúng hay sai?', 'Doan van mieu ta can dung nhieu tinh tu goi hinh, goi cam. Theo em, nhan dinh tren dung hay sai?', 'Đoạn văn miêu tả cần dùng nhiều tính từ gợi hình, gợi cảm.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Tiếng Việt','Lớp 4']::TEXT[], true, 'approved', 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
    ('69f6aea1-457c-461a-9c98-98c8bf14b88d', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 4 AND code = 'VIE') AND code = 'C3' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'essay' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'hard' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'apply' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Em hãy viết đoạn văn (5-6 câu) miêu tả một loài cây mà em yêu thích.', 'Em hay viet doan van (5-6 cau) mieu ta mot loai cay ma em yeu thich.', 'Câu hỏi tự luận — chấm theo rubric của giáo viên.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Tiếng Việt','Lớp 4']::TEXT[], true, 'approved', 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
    ('826969ec-9052-4e57-b50d-3c63d0b13b5d', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 4 AND code = 'VIE') AND code = 'C4' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'true_false' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'hard' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'analyze' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Câu ghép là câu do hai hay nhiều vế câu ghép lại. Câu trên đúng hay sai?', 'Cau ghep la cau do hai hay nhieu ve cau ghep lai. Cau tren dung hay sai?', 'Câu ghép là câu do hai hay nhiều vế câu ghép lại.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Tiếng Việt','Lớp 4']::TEXT[], true, 'approved', 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
    ('feae200a-6bfe-46d6-bffb-9a3bf4662583', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 4 AND code = 'VIE') AND code = 'C5' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'multiple_choice' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'hard' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'evaluate' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Trong các phát biểu sau, phát biểu nào đúng?', 'Trong cac phat bieu sau, phat bieu nao dung?', 'Các vế trong câu ghép có thể nối với nhau bằng quan hệ từ.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Tiếng Việt','Lớp 4']::TEXT[], true, 'approved', 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
    ('39112209-8dfb-418f-aeae-d3a6b647e5fb', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 4 AND code = 'VIE') AND code = 'C6' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'true_false' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'hard' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'create' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Từ ghép là từ được tạo bởi hai tiếng có nghĩa ghép lại, ví dụ ''quần áo''. Theo em, nhận định trên đúng hay sai?', 'Tu ghep la tu duoc tao boi hai tieng co nghia ghep lai, vi du ''quan ao''. Theo em, nhan dinh tren dung hay sai?', 'Từ ghép là từ được tạo bởi hai tiếng có nghĩa ghép lại, ví dụ ''quần áo''.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Tiếng Việt','Lớp 4']::TEXT[], true, 'approved', 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
    ('4abe6b33-68b0-42ed-b5be-f85c3faab443', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 4 AND code = 'VIE') AND code = 'C1' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'multiple_choice' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'very_hard' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'remember' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Nhận định nào sau đây là chính xác?', 'Nhan dinh nao sau day la chinh xac?', 'Bài văn tả cây cối thường tả theo trình tự từ rễ, thân, đến lá, hoa, quả.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Tiếng Việt','Lớp 4']::TEXT[], true, 'approved', 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
