    ('59d29fa0-d289-4f39-9219-2ff85e90433c', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 4 AND code = 'VIE') AND code = 'C5' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'multiple_choice' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'very_hard' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'evaluate' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Chọn phát biểu đúng trong các phương án sau:', 'Chon phat bieu dung trong cac phuong an sau:', 'Bài văn tả con vật cần miêu tả hình dáng và hoạt động của con vật.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Tiếng Việt','Lớp 4']::TEXT[], true, 'approved', 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
    ('d748a1b4-017b-4c43-b299-4bb29b3c59e4', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 4 AND code = 'VIE') AND code = 'C6' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'true_false' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'very_hard' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'create' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Kể chuyện được chứng kiến là kể lại một sự việc có thật mà em đã thấy. Câu trên đúng hay sai?', 'Ke chuyen duoc chung kien la ke lai mot su viec co that ma em da thay. Cau tren dung hay sai?', 'Kể chuyện được chứng kiến là kể lại một sự việc có thật mà em đã thấy.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Tiếng Việt','Lớp 4']::TEXT[], true, 'approved', 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
    ('07edcc0b-b4f1-48f6-9cb7-04fca94f3f0f', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 4 AND code = 'VIE') AND code = 'C1' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'multiple_choice' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'easy' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'remember' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Đâu là nhận định đúng?', 'Dau la nhan dinh dung?', 'Chủ ngữ là bộ phận trả lời cho câu hỏi ''Ai? Cái gì? Con gì?''.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Tiếng Việt','Lớp 4']::TEXT[], true, 'approved', 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
